using System.Collections.Generic;
using UnityEngine;

namespace CloudGarden.Islands
{
    /// <summary>
    /// Creates and caches the materials used by the world. Template materials are generated by the editor
    /// setup script into Resources/Materials so their shader variants are included in player builds; if a
    /// template is missing (e.g. a plain editor run) a runtime fallback is created.
    /// </summary>
    public static class MaterialLibrary
    {
        static readonly Dictionary<long, Material> cache = new Dictionary<long, Material>();
        static Material litTemplate, emissiveTemplate, transparentTemplate, unlitTemplate;

        static Material LoadTemplate(string resourceName, string shaderName, bool transparent, bool emission)
        {
            Material m = Resources.Load<Material>("Materials/" + resourceName);
            if (m != null) return m;

            Shader sh = Shader.Find(shaderName);
            if (sh == null) sh = Shader.Find("Universal Render Pipeline/Lit");
            if (sh == null) sh = Shader.Find("Standard");
            if (sh == null) sh = Shader.Find("Sprites/Default");
            m = new Material(sh);
            m.name = resourceName + "(runtime)";
            if (transparent) MakeTransparent(m);
            if (emission) m.EnableKeyword("_EMISSION");
            return m;
        }

        public static void MakeTransparent(Material m)
        {
            m.SetFloat("_Surface", 1f);
            m.SetFloat("_Blend", 0f);
            m.SetFloat("_SrcBlend", 5f);
            m.SetFloat("_DstBlend", 10f);
            m.SetFloat("_SrcBlendAlpha", 1f);
            m.SetFloat("_DstBlendAlpha", 10f);
            m.SetFloat("_ZWrite", 0f);
            m.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");
            m.renderQueue = 3000;
            m.SetOverrideTag("RenderType", "Transparent");
            m.SetShaderPassEnabled("ShadowCaster", false);
        }

        static void EnsureTemplates()
        {
            if (litTemplate != null) return;
            litTemplate = LoadTemplate("CG_Lit", "Universal Render Pipeline/Lit", false, false);
            emissiveTemplate = LoadTemplate("CG_LitEmissive", "Universal Render Pipeline/Lit", false, true);
            transparentTemplate = LoadTemplate("CG_LitTransparent", "Universal Render Pipeline/Lit", true, false);
            unlitTemplate = LoadTemplate("CG_Unlit", "Universal Render Pipeline/Unlit", false, false);
        }

        static long Key(int kind, Color c, int extra)
        {
            Color32 k = c;
            long v = (((long)k.r << 24) | ((long)k.g << 16) | ((long)k.b << 8) | k.a);
            return v * 64 + kind * 8 + (extra & 7) + ((long)extra << 40);
        }

        static void SetColor(Material m, Color c)
        {
            if (m.HasProperty("_BaseColor")) m.SetColor("_BaseColor", c);
            if (m.HasProperty("_Color")) m.SetColor("_Color", c);
        }

        static void SetTex(Material m, Texture2D tex)
        {
            if (m.HasProperty("_BaseMap")) m.SetTexture("_BaseMap", tex);
            if (m.HasProperty("_MainTex")) m.SetTexture("_MainTex", tex);
        }

        /// <summary>Opaque painted material.</summary>
        public static Material Lit(Color c, float smoothness)
        {
            EnsureTemplates();
            int sm = Mathf.RoundToInt(Mathf.Clamp01(smoothness) * 7f);
            long key = Key(0, c, sm);
            Material m;
            if (cache.TryGetValue(key, out m) && m != null) return m;
            m = new Material(litTemplate);
            SetColor(m, c);
            SetTex(m, TextureFactory.PaintedNeutral());
            if (m.HasProperty("_Smoothness")) m.SetFloat("_Smoothness", sm / 7f);
            if (m.HasProperty("_Metallic")) m.SetFloat("_Metallic", 0f);
            cache[key] = m;
            return m;
        }

        public static Material Lit(Color c) { return Lit(c, 0.25f); }

        /// <summary>Opaque material with a custom texture (island ground, rock...).</summary>
        public static Material Textured(Color tint, Texture2D tex, string key, float tiling)
        {
            EnsureTemplates();
            long k = (long)key.GetHashCode() * 977L + 12345;
            Material m;
            if (cache.TryGetValue(k, out m) && m != null) return m;
            m = new Material(litTemplate);
            SetColor(m, tint);
            SetTex(m, tex);
            if (m.HasProperty("_Smoothness")) m.SetFloat("_Smoothness", 0.1f);
            if (m.HasProperty("_Metallic")) m.SetFloat("_Metallic", 0f);
            cache[k] = m;
            return m;
        }

        /// <summary>Self-lit colored material (glowing crystals, lights).</summary>
        public static Material Emissive(Color c, float intensity)
        {
            EnsureTemplates();
            int it = Mathf.RoundToInt(Mathf.Clamp(intensity, 0f, 7f));
            long key = Key(1, c, it);
            Material m;
            if (cache.TryGetValue(key, out m) && m != null) return m;
            m = new Material(emissiveTemplate);
            SetColor(m, c);
            SetTex(m, TextureFactory.PaintedNeutral());
            m.EnableKeyword("_EMISSION");
            m.globalIlluminationFlags = MaterialGlobalIlluminationFlags.None;
            if (m.HasProperty("_EmissionColor")) m.SetColor("_EmissionColor", c * it);
            if (m.HasProperty("_Smoothness")) m.SetFloat("_Smoothness", 0.5f);
            cache[key] = m;
            return m;
        }

        /// <summary>Semi transparent material (glass, water, ghosts).</summary>
        public static Material Glass(Color c)
        {
            EnsureTemplates();
            long key = Key(2, c, 0);
            Material m;
            if (cache.TryGetValue(key, out m) && m != null) return m;
            m = new Material(transparentTemplate);
            MakeTransparent(m);
            SetColor(m, c);
            if (m.HasProperty("_Smoothness")) m.SetFloat("_Smoothness", 0.8f);
            cache[key] = m;
            return m;
        }

        /// <summary>Transparent textured material (water). Not cached: its offset is animated.</summary>
        public static Material WaterMaterial(Color tint, Texture2D tex)
        {
            EnsureTemplates();
            Material m = new Material(transparentTemplate);
            MakeTransparent(m);
            SetColor(m, tint);
            SetTex(m, tex);
            if (m.HasProperty("_Smoothness")) m.SetFloat("_Smoothness", 0.9f);
            return m;
        }

        public static Material Unlit(Color c)
        {
            EnsureTemplates();
            long key = Key(3, c, 0);
            Material m;
            if (cache.TryGetValue(key, out m) && m != null) return m;
            m = new Material(unlitTemplate);
            SetColor(m, c);
            cache[key] = m;
            return m;
        }

        /// <summary>Unlit material with its own texture (sky backdrop). Not cached.</summary>
        public static Material UnlitTextured(Texture2D tex)
        {
            EnsureTemplates();
            Material m = new Material(unlitTemplate);
            SetColor(m, Color.white);
            SetTex(m, tex);
            return m;
        }
    }
}
